<script setup lang="ts">
import { t as uiText } from '@/locales'

import {SUPPLIER_BUSINESS_CATEGORIES,supplierBusinessLabel} from '@/utils/supplierBusiness'
import {partnerError} from '@/utils/partnerError'
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import PageContainer from '@/components/PageContainer/index.vue'
import BusinessFields from './BusinessFields.vue'
import PartnerFacts from './PartnerFacts.vue'
import PartnerOperationsPanel from './operations/PartnerOperationsPanel.vue'
import SupplierRangePanel from '@/views/supplier/SupplierRangePanel.vue'
import SupplierLifecycleDialog from '@/views/supplier/SupplierLifecycleDialog.vue'
import MasterDataLifecycleDialog from '@/components/MasterDataLifecycleDialog.vue'
import {getCustomerPage,getCustomerDetail,createCustomer,updateCustomer,getCustomerReferences,customerLifecycle} from '@/api/modules/customer'
import {getSupplierPage,getSupplierDetail,getSupplierCenterSnapshot,createInventorySupplier,updateInventorySupplier,type SupplierLifecycleAction} from '@/api/modules/supplier'
import type {SupplierScopeMetadata} from '@/api/modules/supplierRanges'
import {partnerRelations,newRequestId} from '@/api/modules/partner'
import {useUserStore} from '@/stores/user'
import type {BusinessData,PartnerPage,BusinessField} from '@/types/partner'
import {normalizeLegacyProductTarget} from '@/utils/projectRoute'
const props=defineProps<{kind:'customer'|'supplier'}>(),route=useRoute(),router=useRouter(),user=useUserStore()
const supplier=computed(()=>props.kind==='supplier'),title=computed(()=>supplier.value?'供应商管理':'客户管理')
const currentId=computed(()=>supplier.value?String(route.query.code||''):Number(route.params.id||0)),detail=ref<BusinessData>(),relations=ref<BusinessData>(),risks=ref<BusinessData[]>([])
const page=ref<PartnerPage>({content:[],totalElements:0,page:1,size:30,totalPages:0}),filters=reactive({keyword:'',status:'',type:'',category:'',businessCategory:'',page:1})
const loading=ref(false),error=ref(''),dialog=ref(false),busy=ref(false),dirty=ref(false),form=ref<BusinessData>({}),formError=ref('')
const nameKey=computed(()=>supplier.value?'supplierName':'customerName'),typeKey=computed(()=>supplier.value?'supplierType':'customerType'),codeKey=computed(()=>supplier.value?'supplierCode':'customerCode')
const displayCode=(row:BusinessData)=>supplier.value?row.shortCode||'未设置简码':row[codeKey.value]
function metadataSaved(code:string,metadata:SupplierScopeMetadata){if(!supplier.value||currentId.value!==code||detail.value?.supplierCode!==code||metadata.supplierCode!==code||metadata.version<Number(detail.value.version||0))return;detail.value={...detail.value,shortCode:metadata.shortCode,version:metadata.version}}
const typeName=(v:string)=>v==='company'?'公司':v==='person'?'个人':'类型待补'
const statusName=(v:string)=>({draft:'草稿',active:'启用',inactive:'停用'} as Record<string,string>)[v]||v
const canWrite=computed(()=>user.hasPermission(supplier.value?'partner:write':detail.value?'customer:edit':'customer:create'))
const canEditExisting=computed(()=>user.hasPermission(supplier.value?'partner:write':'customer:edit'))
const canMoney=computed(()=>user.hasPermission('finance:read'))
const canCustomerLifecycle=computed(()=>!supplier.value&&user.hasPermission('customer:edit')&&user.hasPermission('customer:view'))
const customerLifecycleTarget=ref<{id:number,name:string,code:string}>()
function customerAction(row:BusinessData,action:SupplierLifecycleAction){lifecycleAction.value=action;customerLifecycleTarget.value={id:row.customerId,name:row.customerName,code:row.customerCode}}
async function customerCompleted(result:unknown){customerLifecycleTarget.value=undefined;const r=result as {id:number;deleted:boolean};if(r.deleted&&Number(currentId.value)===Number(r.id)){detail.value=undefined;relations.value=undefined;await router.replace('/customers')}else await load()}
const canSupplierLifecycle=computed(()=>supplier.value&&canWrite.value&&user.hasPermission('supplier:view'))
const lifecycleTarget=ref<{supplierCode:string;supplierName:string}>(),lifecycleAction=ref<SupplierLifecycleAction>('delete')
const lifecycleContext=computed(()=>JSON.stringify([currentId.value,user.token,user.permissions]))
function lifecycle(row:BusinessData,action:SupplierLifecycleAction){if(!canSupplierLifecycle.value)return;lifecycleAction.value=action;lifecycleTarget.value={supplierCode:row.supplierCode,supplierName:row.supplierName}}
async function lifecycleCompleted(result:{supplierCode:string;deleted:boolean}){lifecycleTarget.value=undefined;if(result.deleted&&String(currentId.value)===result.supplierCode){detail.value=undefined;relations.value=undefined;await router.replace('/suppliers')}else await load()}
let seq=0
async function load(reset=false){if(reset)filters.page=1;const serial=++seq,token=user.token,target=currentId.value;loading.value=true;error.value=''
 const current=()=>seq===serial&&user.token===token&&currentId.value===target
 if(detail.value&&(supplier.value?detail.value.supplierCode!==target:Number(detail.value.customerId)!==Number(target))){detail.value=undefined;relations.value=undefined}
 try{if(target){const d=supplier.value?await getSupplierDetail(String(target)):await getCustomerDetail(Number(target));if(!current())return;detail.value=d as BusinessData;if(user.hasPermission('partner:view')){const related=await partnerRelations(supplier.value?'suppliers':'customers',target);if(!current())return;relations.value=related}}
 else{detail.value=undefined;relations.value=undefined;const result=supplier.value?await getSupplierPage({...filters}):await getCustomerPage({...filters});if(!current())return;page.value=result}
 if(route.path.endsWith('/create')||route.path.endsWith('/edit'))edit()
 }catch(e){if(current())error.value=partnerError(e)}finally{if(current())loading.value=false}}
watch(()=>route.fullPath,()=>void load(),{immediate:true})
function open(row:BusinessData){if(supplier.value)return router.push({path:'/suppliers',query:{code:row.supplierCode,from:route.fullPath}});else return router.push({path:'/customers/'+row.customerId,query:{from:route.fullPath}})}
async function editRow(row:BusinessData){await open(row);await load();if(detail.value)edit()}
function back(){const source=String(route.query.from||'');router.push(source.startsWith('/')?source:supplier.value?'/suppliers':'/customers')}
function edit(){form.value={...(detail.value?JSON.parse(JSON.stringify(detail.value)):{[nameKey.value]:'',[typeKey.value]:'unknown',contactPhone:'',status:'draft',supplyCategories:[]}),...(supplier.value?{businessCategories:detail.value?.businessCategories||[]}:{}),requestId:newRequestId()};formError.value='';dialog.value=true;dirty.value=false}
const primary=computed<BusinessField[]>(()=>[{key:nameKey.value,label:'常用名称',required:true},{key:typeKey.value,label:'类型',type:'select',options:[{value:'unknown',label:'待补充'},{value:'company',label:'公司'},{value:'person',label:'个人'}]},{key:'contactPhone',label:'电话／常用联系方式'}])
const secondary=computed<BusinessField[]>(()=>[{key:supplier.value?'contactPerson':'contactName',label:'联系人'},{key:'contactEmail',label:'邮箱'},{key:supplier.value?'region':'countryCode',label:'地区'},{key:supplier.value?'shortName':'customerShortName',label:'简称'},...(detail.value?.status==='inactive'?[]:[{key:'status',label:'状态',type:'select' as const,options:[{value:'draft',label:'草稿'},{value:'active',label:'启用'},]}]),...(supplier.value?(canMoney.value?[{key:'paymentTerm',label:'结算说明'}]:[]):[{key:'address',label:'地址',type:'textarea' as const},{key:'sourceType',label:'客户来源'},{key:'website',label:'网站'},{key:'websiteCustomerId',label:'网站客户编号'}]),{key:'remark',label:'备注',type:'textarea'}])
async function close(){if(dirty.value){try{await ElMessageBox.confirm(uiText('放弃本次未保存内容？'),uiText('关闭表单'))}catch{return}}dialog.value=false;dirty.value=false}
async function save(){busy.value=true;formError.value='';try{let saved:BusinessData;if(supplier.value)saved=detail.value?await updateInventorySupplier(detail.value.supplierCode,form.value as never):await createInventorySupplier(form.value as never);else saved=detail.value?await updateCustomer(detail.value.customerId,form.value):await createCustomer(form.value);dialog.value=false;dirty.value=false;ElMessage.success(uiText('已保存'));if(supplier.value)await router.replace({path:'/suppliers',query:{code:saved.supplierCode,from:String(route.query.from||'/suppliers')}});else await router.replace({path:'/customers/'+saved.customerId,query:{from:String(route.query.from||'/customers')}});await load()}catch(e){formError.value=partnerError(e)}finally{busy.value=false}}
function business(kind:string,id:number){router.push({path:'/'+kind,query:{id,from:route.fullPath}})}
function newSale(){router.push({path:'/partner-sales',query:{customerId:currentId.value,new:'1',from:route.fullPath}})}
function samples(){router.push({path:'/samples',query:{customerId:currentId.value,customerContext:currentId.value,from:route.fullPath}})}
async function loadRisks(){const snapshot=await getSupplierCenterSnapshot();risks.value=snapshot.risks}
function oldLink(path:string){if(path)router.push(normalizeLegacyProductTarget(path))}
onBeforeRouteLeave(async()=>{if(!dirty.value)return true;try{await ElMessageBox.confirm(uiText('本次填写尚未保存，确定离开？'),uiText('未保存内容'));return true}catch{return false}})
</script>
<template><PageContainer :title="detail?String(detail[nameKey]):title" class="master-page" :class="{'supplier-master':supplier}">
 <template #actions><el-button v-if="detail" @click="back">{{ uiText("返回来源") }}</el-button><el-button v-if="canWrite&&(!currentId||detail)" type="primary" @click="edit">{{detail?uiText('编辑档案'):supplier?uiText('新增供应商'):uiText('新增客户')}}</el-button><template v-if="detail&&canSupplierLifecycle"><el-button @click="lifecycle(detail,detail.status==='inactive'?'activate':'deactivate')">{{detail.status==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button type="danger" plain @click="lifecycle(detail,'delete')">{{ uiText("删除") }}</el-button></template><template v-if="detail&&canCustomerLifecycle"><el-button @click="customerAction(detail,detail.status==='inactive'?'activate':'deactivate')">{{detail.status==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button type="danger" plain @click="customerAction(detail,'delete')">{{ uiText("删除") }}</el-button></template><template v-if="detail&&!supplier&&user.hasPermission('partner:write')"><el-button @click="newSale">{{ uiText("登记询价") }}</el-button><el-button @click="samples">{{ uiText("样品与寄样") }}</el-button></template></template>
 <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load()">{{ uiText("重新加载") }}</el-button></el-alert>
 <template v-if="!currentId"><div class="master-filter"><el-input v-model="filters.keyword" clearable :placeholder="supplier?uiText('搜索名称、简码或联系人'):uiText('搜索名称、编码或联系人')" @keyup.enter="load(true)"/><el-select v-model="filters.type" clearable :placeholder='uiText("全部类型")' @change="load(true)"><el-option :label='uiText("公司")' value="company"/><el-option :label='uiText("个人")' value="person"/><el-option :label='uiText("待补充")' value="unknown"/></el-select><el-select v-if="supplier" v-model="filters.businessCategory" clearable :placeholder="uiText('全部业务分类')" :aria-label="uiText('供应商业务分类筛选')" @change="load(true)"><el-option v-for="category in SUPPLIER_BUSINESS_CATEGORIES" :key="category.value" :label="uiText(category.label)" :value="category.value"/></el-select><el-select v-model="filters.status" clearable :placeholder='uiText("全部状态")' @change="load(true)"><el-option :label='uiText("草稿")' value="draft"/><el-option :label='uiText("启用")' value="active"/><el-option :label='uiText("停用")' value="inactive"/></el-select><el-button @click="load(true)">{{ uiText("查询") }}</el-button></div>
  <div class="master-list" v-loading="loading"><el-empty v-if="!page.content.length&&!loading" :description='uiText("暂无资料，可单条新增")'/><article v-for="row in page.content" :key="row[codeKey]" class="master-row"><div><el-button link type="primary" @click="open(row)">{{row[nameKey]}}</el-button><p class="muted">{{displayCode(row)}}</p></div><div>{{typeName(row[typeKey])}} · {{statusName(row.status)}}<p v-if="supplier" class="muted">{{uiText(supplierBusinessLabel(row.businessCategories))}}</p></div><div>{{row.contactPhone||row.contactEmail||uiText('联系方式可后补')}}<p class="muted">{{row.contactPerson||row.contactName}}</p></div><div class="master-row-actions"><el-button link @click="open(row)">{{ uiText("查看关联") }}</el-button><el-button v-if="canEditExisting" link @click="editRow(row)">{{ uiText("编辑") }}</el-button><template v-if="canSupplierLifecycle"><el-button link @click="lifecycle(row,row.status==='inactive'?'activate':'deactivate')">{{row.status==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button link type="danger" @click="lifecycle(row,'delete')">{{ uiText("删除") }}</el-button></template><template v-if="canCustomerLifecycle"><el-button link @click="customerAction(row,row.status==='inactive'?'activate':'deactivate')">{{row.status==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button link type="danger" @click="customerAction(row,'delete')">{{ uiText("删除") }}</el-button></template></div></article></div>
  <div class="master-footer"><span>{{ uiText("共 ") }}{{page.totalElements}}{{ uiText(" 条") }}</span><el-pagination v-model:current-page="filters.page" :page-size="30" :pager-count="5" layout="prev,pager,next" :total="page.totalElements" @current-change="load()"/></div>
  <details v-if="supplier" class="master-risk" @toggle="($event.target as HTMLDetailsElement).open&&loadRisks()"><summary>{{ uiText("原供货风险与提醒") }}</summary><p v-for="(risk,n) in risks" :key="n"><el-button link @click="oldLink(risk.targetPath)">{{risk.title}}</el-button> · {{risk.owner}} · {{risk.action}}</p><p v-if="!risks.length" class="muted">{{ uiText("暂无风险记录") }}</p></details>
 </template>
 <div v-else-if="detail" class="master-scroll" v-loading="loading"><section class="master-panel"><div class="master-facts"><div><small>{{supplier?uiText('供应商简码'):uiText('编号')}}</small><p>{{displayCode(detail)}}</p></div><div><small>{{ uiText("类型／状态") }}</small><p>{{typeName(detail[typeKey])}} · {{statusName(detail.status)}}</p></div><div v-if="supplier"><small>{{uiText("业务分类")}}</small><p>{{uiText(supplierBusinessLabel(detail.businessCategories))}}</p></div><div><small>{{ uiText("联系方式") }}</small><p>{{detail.contactPhone||detail.contactEmail||uiText('可后补')}}</p></div></div><el-alert v-if="detail.needsReview" :title='uiText("历史身份存在歧义，请核对后再用于新业务")' type="warning" :closable="false"/><details><summary>{{ uiText("更多资料") }}</summary><p>{{ uiText("联系人 ") }}{{detail.contactPerson||detail.contactName||uiText('未填')}}{{ uiText(" · 邮箱 ") }}{{detail.contactEmail||uiText('未填')}}</p><p>{{ uiText("地区 ") }}{{detail.region||detail.countryCode||uiText('未填')}}{{ uiText(" · 地址 ") }}{{detail.address||uiText('未填')}}</p><p>{{detail.remark||detail.sourceType||''}}</p><p v-if="canMoney">{{detail.paymentTerm}}</p></details></section>
  <template v-if="supplier"><section class="master-panel"><SupplierRangePanel :supplier-code="detail.supplierCode" :can-write="canWrite" @metadata-saved="metadataSaved"/></section><section class="master-panel"><PartnerOperationsPanel kind="supplier_quote" :supplier-code="detail.supplierCode" :source-name="detail.supplierName"/></section><section class="master-panel"><PartnerOperationsPanel kind="sample_fee" :supplier-code="detail.supplierCode"/></section></template>
  <section v-if="relations?.products" class="master-panel"><h3>{{ uiText("合作产品") }}</h3><div v-for="p in relations.products.content" :key="p.id" class="master-related"><el-button link @click="business('partner-products',p.id)">{{p.name}}</el-button><span class="muted">{{p.code}}</span></div><p v-if="!relations.products.content.length" class="muted">{{ uiText("暂无关联产品") }}</p></section>
  <section v-if="relations?.sales" class="master-panel"><h3>{{supplier?uiText('销售与待结业务'):uiText('询价与订单')}}</h3><p v-for="sum in relations.pending||[]" :key="sum.currency" class="muted">{{sum.currency}}{{ uiText(" 货款待结 ") }}{{(sum.payRemainingCents/100).toFixed(2)}}{{ uiText(" · 佣金待核销 ") }}{{(sum.feeRemainingCents/100).toFixed(2)}}{{ uiText(" · 待核对 ") }}{{sum.reviewCount}}{{ uiText(" 单") }}</p><div v-for="s in relations.sales.content" :key="s.id" class="master-related"><div><el-button link @click="business('partner-sales',s.id)">{{s.code}} · {{s.name}}</el-button><p v-if="supplier&&canMoney" class="muted"><template v-for="st in s.stats?.settlements||[]" :key="st.supplierCode"><span v-if="st.supplierCode===detail.supplierCode">{{ uiText("货款待结 ") }}{{s.currency}} {{(st.payRemainingCents/100).toFixed(2)}}{{ uiText(" · 佣金待核销 ") }}{{(st.feeRemainingCents/100).toFixed(2)}} <el-tag v-if="st.agreement.review" size="small" type="warning">{{ uiText("待核对") }}</el-tag></span></template></p></div><span class="muted">{{({draft:uiText('草稿'),quoted:uiText('报价已确认'),confirmed:uiText('订单已确认'),closed:uiText('已关闭')} as Record<string,string>)[s.status]||s.status}}</span></div><p v-if="!relations.sales.content.length" class="muted">{{ uiText("暂无销售记录") }}</p></section>
  <section v-if="relations?.samples" class="master-panel"><h3>{{supplier?uiText('关联样品'):uiText('样品与寄样')}}</h3><div v-for="s in relations.samples.content" :key="s.id" class="master-related"><el-button link @click="business('samples',s.id)">{{s.name}} · {{s.specName}}</el-button><span>{{ uiText("在库 ") }}{{s.balances.onhand}} · {{supplier?uiText('全部待还'):uiText('本客户待还')}} {{supplier?s.balances.borrowed:s.customerOutstanding}}</span></div><p v-if="!relations.samples.content.length" class="muted">{{ uiText("暂无样品往来") }}</p></section>
  <template v-if="supplier"><section class="master-panel"><details><summary>{{ uiText("原供货记录（") }}{{detail.supplyRecords?.length||0}}）</summary><div v-for="r in detail.supplyRecords||[]" :key="r.recordId" class="master-related"><div><el-button link @click="oldLink(r.targetPath)">{{r.itemName}}</el-button><p class="muted">{{r.itemCode}} · {{r.relatedProduct}} · {{r.status}}</p><p v-if="canMoney">{{r.currency}} {{r.unitPrice??uiText('未填')}}{{ uiText(" · 最近供货 ") }}{{r.lastDeliveryDate||uiText('未填')}}</p></div></div></details><details><summary>{{ uiText("原研发项目（") }}{{detail.relatedProjects?.length||0}}）</summary><p v-for="p in detail.relatedProjects||[]" :key="p.projectCode"><el-button link @click="oldLink(p.targetPath)">{{p.projectName}}</el-button> · {{p.roleSummary}} · {{p.stage}}</p></details><details><summary>{{ uiText("原资质文件（") }}{{detail.qualificationFiles?.length||0}}）</summary><p v-for="(f,n) in detail.qualificationFiles||[]" :key="n">{{f.fileName}} · {{f.fileType}} · {{f.validUntil}} · {{uiText(f.statusLabel)}}</p></details></section></template>
  <template v-else><section v-if="detail.relatedOrders?.length" class="master-panel"><h3>{{ uiText("关联订单／原需求") }}</h3><p v-for="(r,n) in detail.relatedOrders" :key="n"><el-button v-if="r.recordId" link @click="business('partner-sales',r.recordId)">{{r.orderCode}} · {{r.orderTitle}}</el-button><span v-else>{{r.orderCode}} · {{r.orderTitle}} · {{r.status}}</span></p></section><section v-if="detail.operationLogs?.length" class="master-panel"><details><summary>{{ uiText("档案维护历史") }}</summary><p v-for="(log,n) in detail.operationLogs" :key="n">{{String(log.time).slice(0,19)}} · {{log.operator}} · {{log.action}}</p></details></section></template>
 </div>
 <el-dialog v-model="dialog" :title="(detail?uiText('编辑'):uiText('新增'))+(supplier?uiText('供应商'):uiText('客户'))" width="min(600px,95vw)" :close-on-click-modal="false" :before-close="close" append-to-body><el-form label-position="top" @input="dirty=true" @change="dirty=true"><BusinessFields :model="form" :fields="primary"/><el-form-item v-if="supplier" :label="uiText('业务分类')"><el-select v-model="form.businessCategories" multiple :aria-label="uiText('供应商业务分类')" :placeholder="uiText('选择该供应商承担的业务，可多选')"><el-option v-for="category in SUPPLIER_BUSINESS_CATEGORIES" :key="category.value" :label="uiText(category.label)" :value="category.value"/></el-select><p class="muted">{{uiText("开模申请与研发开模只显示开模供应商；同一家公司可兼任两类。")}}</p></el-form-item><details><summary>{{ uiText("更多信息（可后补）") }}</summary><BusinessFields :model="form" :fields="secondary"/><el-form-item v-if="supplier" :label='uiText("供应品类")'><el-select v-model="form.supplyCategories" multiple filterable allow-create><el-option v-for="v in ['原材料','模具','包装','合作产品']" :key="v" :label="v" :value="v"/></el-select></el-form-item></details><el-alert v-if="formError" :title="formError" type="error" :closable="false"/></el-form><template #footer><el-button @click="close">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="busy" @click="save">{{ uiText("保存") }}</el-button></template></el-dialog>
 <MasterDataLifecycleDialog v-if="!supplier" :record="customerLifecycleTarget" kind-label="客户" :action="lifecycleAction" :editable="canCustomerLifecycle" :context="lifecycleContext" :load="getCustomerReferences" :perform="customerLifecycle" @close="customerLifecycleTarget=undefined" @completed="customerCompleted" @open="oldLink"/>
 <SupplierLifecycleDialog v-if="supplier" :supplier="lifecycleTarget" :action="lifecycleAction" :editable="canSupplierLifecycle" :context="lifecycleContext" @close="lifecycleTarget=undefined" @completed="lifecycleCompleted" @open="oldLink"/>
 </PageContainer></template>
